window.COMBAT_BOOK=[{"title": "Gameplay & Rulebook", "kicker": "PLAYTEST EDITION / V2", "blocks": [{"type": "p", "text": "Build your team. Spend wisely. Take the field."}, {"type": "box", "title": "THE BROADCAST IS YOURS", "text": "A two-player card battle of rival champions, limited coins, and carefully timed surprises."}, {"type": "p", "text": "22 November 2026 | Digital playtest rules. The latest opening-turn experiment is explained on page 22. This is a playtest edition, not a final balance claim."}], "visual": "cover", "caption": null}, {"title": "Start here", "kicker": "READ THE GAME IN LAYERS", "blocks": [{"type": "p", "text": "Learn the basics on pages 3-10, add specials and modifiers on pages 11-15, then use the advanced rules when a card calls for them."}, {"type": "list", "items": ["03  Your objective & the three currencies", "04  Build your decks", "05  Set up the opening field", "06  Read a character card", "07  Read a modifier card", "08  The battlefield", "09  Turn order & readiness", "10  Attacks, damage & defeat", "11  Guard & Exposure", "12  Pay for a special", "13  Play a modifier", "14  One response, no chains", "15  Bonuses, caps & durations", "16  Extra attacks & redirection", "17  Control, recovery & revival", "18  Copies, searches & ownership", "19  Guided opening turns", "20  Worked modifier example", "21  Endings & common questions", "22  Playtest variants & next steps", "23  Timing glossary", "24  Quick reference"]}, {"type": "box", "title": "CARD TEXT FOR THIS EDITION", "text": "Use the revised v2 text in the searchable Card Reference. Older printed specials can differ. Specific card permissions still obey the global action, response, attack and bonus limits."}], "visual": null, "caption": null}, {"title": "Win the field", "kicker": "01 / THE OBJECTIVE", "blocks": [{"type": "p", "text": "At the end of your own turn, you lose if your character field is empty. There are no player life points in this edition."}, {"type": "box", "title": "YOU GET A CHANCE TO REBUILD", "text": "If your opponent clears your field, you still take your next turn. Buy or legally return a character before your cleanup to stay in the game."}, {"type": "p", "text": "If both players lose simultaneously, the game is a draw. A stalled game can also draw; see page 21."}, {"type": "wallets"}, {"type": "box", "title": "COINS ARE A BATTLE BUDGET", "text": "Each battle begins with 100 Battle Coins. No automatic income and no refunds. Ad Bucks tickets are the proposed earned wallet; Spotlight Shards are the proposed premium wallet. Neither pays battle costs."}], "visual": null, "caption": null}, {"title": "Build your decks", "kicker": "02 / BEFORE THE MATCH", "blocks": [{"type": "list", "items": ["12 different character cards in your character deck.", "12 different modifier cards in a separate modifier deck.", "No duplicate card in either deck.", "At most 2 Legendary characters in your character deck.", "At most 1 Legendary under your control in the field.", "Mix Animal, Human, Magic and Shadow freely; factions do not restrict slots."]}, {"type": "factions"}, {"type": "box", "title": "A BALANCED START", "text": "As a first experiment, bring a mix of affordable characters, durable defenders and effects you can afford after setup. Save coins for specials and modifiers; an expensive field can leave no budget for surprises."}, {"type": "p", "text": "Legendary is a category in this draft. Rarity tiers, paid packs and pack odds are outside these battle rules."}], "visual": "setup-numbers.svg", "caption": null}, {"title": "Set up the match", "kicker": "03 / REVEAL TOGETHER", "blocks": [{"type": "list", "items": ["Each player takes 100 Battle Coins. Shuffle the two decks separately.", "Draw 5 characters and 3 modifiers.", "Secretly choose 2 characters you can afford together. Reveal simultaneously and pay both purchase costs.", "Put those characters in play at full printed Defense. Keep remaining cards in hand.", "Determine the first player randomly. Keep character and modifier graveyards separate."]}, {"type": "box", "title": "OPENING ATTACK RULE", "text": "Digital rule: both players cannot declare a normal or extra attack on their first turn. The second player cannot attack on their first turn with an eligible opening character."}, {"type": "p", "text": "Opening characters are ready; the opening attack restriction still applies. The older rule and both-players-skip experiment is on page 22."}, {"type": "box", "title": "SETUP EDGE CASE", "text": "The saved draft does not specify a redraw if the opening hand cannot afford two characters. The digital build should flag this for a pre-match ruling rather than silently invent a mulligan."}], "visual": "setup-numbers.svg", "caption": null}, {"title": "Read a character", "kicker": "04 / KNOW WHAT YOU ARE BUYING", "blocks": [{"type": "character"}, {"type": "list", "items": ["Name and faction identify the exact card for effects and signature bonuses.", "Coin value: purchase cost paid to put the character into play.", "The + number: coin cost to activate its special. It is not income.", "Attack: its printed combat damage potential.", "Printed Defense: its maximum health. Track damage separately.", "Special: read the revised effect, timing and any once-per-game limit."]}, {"type": "box", "title": "ILLUSTRATED DATA, NOT A NEW CARD", "text": "The teaching panel uses Quacklash's v2 values: cost 4, special cost 2, Attack 5 and printed Defense 20. The book does not overwrite card artwork or production files."}], "visual": null, "caption": null}, {"title": "Read a modifier", "kicker": "05 / EVERY CARD HAS A BASE EFFECT", "blocks": [{"type": "modifier"}, {"type": "list", "items": ["Pay the modifier's coin cost when you play it.", "Card Effect works without the named signature character, if its targets are legal.", "Special Bonus is optional, costs no extra coins, and requires its exact stated condition.", "Timing tells you when it can be played.", "Discard the resolved card to your modifier graveyard unless its text returns it."]}, {"type": "box", "title": "NAMED PARTNER IS A BONUS", "text": "A modifier is not locked to its signature partner. Check the base effect first, then the named condition. A bonus cannot ignore a required base target unless it explicitly offers an alternative."}], "visual": null, "caption": null}, {"title": "Your side of the board", "kicker": "06 / FIVE SLOTS, MANY PLANS", "blocks": [{"type": "p", "text": "You may control up to 5 characters, including at most 1 Legendary. Faction symbols are reminders, not slot restrictions."}, {"type": "box", "title": "SEPARATE YOUR ZONES", "text": "Keep character deck, character graveyard, modifier deck and modifier graveyard distinct. Your hand holds both card types. Battle and modifier spaces hold resolving cards; they do not create extra field slots."}, {"type": "p", "text": "For tabletop play, cards are 2.5 x 3.5 inches. The board uses 3 x 4.25-inch spaces for sleeve clearance. The diagram is a rules schematic, not a scale print template."}], "visual": "battlefield.svg", "caption": null}, {"title": "Take your turn", "kicker": "07 / FOUR STEPS", "blocks": [{"type": "box", "title": "1. REFRESH", "text": "Expire start-of-turn effects. Reset your own-turn allowances and your opponent's response allowance. Draw 1 character and 1 modifier; skip the draw from an empty deck."}, {"type": "box", "title": "2. PREPARE", "text": "In any order, you may buy 1 ordinary character, use 1 permitted special, and play 1 permitted modifier. These are separate allowances. You may pass."}, {"type": "box", "title": "3. BATTLE", "text": "Declare 1 normal attack with a ready character. Announce attacker and defender, apply legal attacking effects, allow 1 defensive response, then resolve. A card may grant at most 1 extra attack."}, {"type": "box", "title": "4. CLEANUP", "text": "Resolve effect endings and temporary returns, then discard down to 5 characters and 5 modifiers in hand. If your field is empty, you lose."}, {"type": "p", "text": "A character entering play this turn must wait until its controller's next turn to attack or activate its special, unless the effect explicitly says Ready. Ready never overrides the opening attack restriction."}], "visual": "turn-flow.svg", "caption": null}, {"title": "Attack and take damage", "kicker": "08 / DAMAGE STAYS", "blocks": [{"type": "list", "items": ["Choose an eligible attacker and an opposing character already in play.", "Announce both targets before using attacking effects.", "Offer the defender their remaining response.", "Deal damage after Guard and Exposure. Defenders do not normally strike back.", "At zero remaining health, immediately send the defeated card to its original owner's character graveyard."]}, {"type": "box", "title": "THE CALCULATION", "text": "Remaining health = printed Defense - damage taken. Combat damage = max(0, final Attack - Guard). Final Attack cannot fall below zero; if it is zero, combat damage is zero even against Exposure."}, {"type": "box", "title": "EXAMPLE", "text": "A 20-Defense character already has 5 damage. It gains 10 Guard, then takes a 25-Attack hit: 15 new damage, 20 total, defeated."}, {"type": "p", "text": "Damage persists between turns. There is no ordinary healing in this edition. A card that leaves play and is later bought again starts fresh, with its costs paid again."}], "visual": "damage-example.svg", "caption": null}, {"title": "Guard is not health", "kicker": "09 / TEMPORARY PROTECTION", "blocks": [{"type": "p", "text": "Temporary Defense bonuses become Guard. Temporary Defense reductions become Exposure, a penalty to Guard. Neither changes printed Defense or removes damage."}, {"type": "box", "title": "EXPOSURE EXAMPLE", "text": "A fresh 20-Defense character has 5 Exposure. A 10-Attack hit deals 15 damage. The character survives with 5 health. Exposure alone cannot defeat it before damage is dealt."}, {"type": "box", "title": "COMBINED EXAMPLE", "text": "10 Guard and 5 Exposure make net Guard 5. A 15-Attack hit deals 10 damage. At zero final Attack it still deals zero, even if net Guard is negative."}, {"type": "box", "title": "DIRECT DAMAGE", "text": "Direct-damage effects bypass Guard, do not count as attacks, do not spend the attack allowance and do not open another response window."}, {"type": "p", "text": "Guard for a battle is spent after that battle. Follow duration wording: next-battle effects and for-this-battle effects end at different times; see page 15."}], "visual": "damage-example.svg", "caption": null}, {"title": "Activate a special", "kicker": "10 / PAY THE + COST", "blocks": [{"type": "p", "text": "On your own turn, activate at most 1 special across your entire team. The character must be in play and ready. Choose legal targets and pay its + cost."}, {"type": "list", "items": ["Action: use only in Prepare.", "Response: use only in your defensive response window. It does not spend your next own-turn special.", "Either: use in Prepare, while applying your attacking effects, or as a relevant response."]}, {"type": "box", "title": "MAKE THE TARGET LEGAL FIRST", "text": "You cannot pay for an ability with no legal target. If a later response removes the targets, the remaining effect can fail and the paid cost stays spent."}, {"type": "box", "title": "ONCE PER GAME MEANS THE WHOLE GAME", "text": "Track this on the card across zone changes and temporary control. Leaving play does not refresh the limit. Narrow automatic card reminders do not grant extra actions."}, {"type": "p", "text": "Discounts apply after surcharges and cannot make costs negative. Discounts do not grant additional activations. There are no free entry-special chains or uncapped passive auras."}], "visual": "C001.png", "caption": null}, {"title": "Play a modifier", "kicker": "11 / BASE EFFECT + SPECIAL BONUS", "blocks": [{"type": "p", "text": "You may play at most 1 modifier on your own turn, within its timing window. A defensive modifier uses your one response for the opponent's turn instead."}, {"type": "list", "items": ["Announce the card, targets and cost.", "Pay once. Check the Card Effect and optional Special Bonus.", "Let the defender cancel an announced modifier if they still have a legal response.", "Resolve response first, then the modifier if it was not canceled.", "Discard it unless an effect explicitly returns it."]}, {"type": "box", "title": "A BONUS IS NOT ANOTHER CARD", "text": "The modifier's base and signature bonus combine into one effect before the cap. For most signature modifiers, the chosen ally must be the named character. Scout and Echo instead check whether you control the named character; follow the exact text."}, {"type": "p", "text": "A legal optional stat change may do nothing and still allow the bonus. Conditions are checked at resolution. M002 and M013 have no signature bonus in this draft because their historical partners are unidentified."}], "visual": "M001.png", "caption": null}, {"title": "One response, no chains", "kicker": "12 / KEEP THE MOMENT MOVING", "blocks": [{"type": "p", "text": "The defender gets 1 response total for the entire opposing turn: a Response/Either special OR a legal modifier. Passing an early window preserves the response for a later legal window."}, {"type": "list", "items": ["Modifier window: after a modifier is announced, before it resolves.", "Attack window: after targets and attacking effects are known.", "Response resolves first. Nobody responds to a response.", "A response must affect the threatened ally, modifier or battle; it is not a free unrelated draw action."]}, {"type": "box", "title": "CANCELLATION COSTS SOMETHING", "text": "Canceling a modifier stops both its base and bonus; coins remain spent. A canceled declared attack uses that attack allowance."}, {"type": "box", "title": "EXAMPLE", "text": "You cancel an opponent's modifier in Prepare. When they attack later that turn, you have no response left. You still receive your ordinary own-turn allowances next turn."}], "visual": "response-flow.svg", "caption": null}, {"title": "Bonuses without piles", "kicker": "13 / STRONGEST OF EACH SIGN", "blocks": [{"type": "p", "text": "For each character, count only its strongest Attack bonus, strongest Attack penalty, strongest Guard bonus and strongest Exposure. Each amount is capped at 15. Separate sources do not add on the same statistic."}, {"type": "box", "title": "BASE + SIGNATURE", "text": "If one modifier gives +10 Attack and its own signature adds +5, that one effect is +15. A separate +5 source does not make it +20."}, {"type": "list", "items": ["Next battle: lasts until the character's next battle or the start of the effect controller's next turn, whichever comes first. That battle consumes all next-battle effects on both participants.", "Canceled before battle: next-battle effects remain. For-this-battle effects expire if that attack is canceled.", "Remove a stat effect: remove one chosen source, not damage. A weaker still-present source may then apply.", "Printed-stat replacement: latest legal replacement applies; health, damage and identity stay unchanged."]}, {"type": "p", "text": "Transfers grant only the actual final Attack lost after the new reduction. A weaker reduction that changes nothing transfers zero. Defense theft becomes Exposure and Guard, never healing."}], "visual": "bonus-cap.svg", "caption": null}, {"title": "Extra attacks & redirects", "kicker": "14 / TWO DECLARATIONS MAXIMUM", "blocks": [{"type": "box", "title": "ONE NORMAL + ONE GRANTED EXTRA", "text": "An effect must explicitly grant an extra attack. All sources share a limit of 1 extra per player turn. It happens after the normal attack resolves or is canceled, before cleanup."}, {"type": "p", "text": "An extra-attack grant does not make a character Ready. Pick a legal ready attacker and follow the grant's penalties. Several grants do not stack, and an extra attack cannot grant another extra attack."}, {"type": "box", "title": "OPENING RESTRICTION WINS", "text": "The digital v2 players cannot use a normal or extra attack on their own first turn. Ready and extra-attack cards cannot bypass this."}, {"type": "box", "title": "REDIRECT ONCE", "text": "An attack can be redirected once to a legal target already in play. No new response window opens. Attacker bonuses stay on the attacker; defender effects stay on the card that received them."}, {"type": "p", "text": "A for-this-battle effect expires if its target stops participating. A next-battle effect waits for that character's next battle. Copying and redirecting never bypass target restrictions or global caps."}], "visual": "C174.png", "caption": null}, {"title": "Return to the field", "kicker": "15 / CONTROL IS NOT OWNERSHIP", "blocks": [{"type": "box", "title": "TEMPORARY CONTROL", "text": "Unless narrower text says otherwise, choose an opposing non-Legendary already in play and have an open slot. Keep its damage and original owner. Control ends at cleanup. It cannot use its special; it cannot attack unless the effect permits Ready, using your existing allowances."}, {"type": "box", "title": "RECOVER TO HAND", "text": "Ordinary recovery returns a card to its owner's hand, not directly to play. Pay its purchase cost to buy it again. If it later enters play, it begins at full health and normally waits."}, {"type": "box", "title": "RESURRECTION", "text": "This modifier puts your own non-Legendary from your character graveyard into an open slot at full health with Ready, without its purchase cost. Its special is forbidden. It may use an available attack but grants none. At cleanup it returns to its owner's graveyard if still in play."}, {"type": "p", "text": "A defeated controlled card always goes to its original owner's graveyard. Temporary control never permanently steals it. The one-Legendary and five-character field limits still apply."}], "visual": "M010.png", "caption": null}, {"title": "Copies, searches & costs", "kicker": "16 / FOLLOW THE EXACT PERMISSION", "blocks": [{"type": "box", "title": "COPIES", "text": "Only named printed statistics or whitelisted simple modifier base effects may be copied. Never copy identity, category, specials, signature bonuses, entry events, control, revival, action grants, discounts or another copy effect."}, {"type": "p", "text": "Transformation uses an explicit whitelist in its card-reference record. It does not authorize copying any modifier you can see. Printed-stat replacements leave maximum health and existing damage unchanged."}, {"type": "box", "title": "SEARCH & DRAW", "text": "Unqualified hand, deck and graveyard effects refer to your own characters. Follow text that names modifiers or the opponent. Reveal only what is requested; shuffle after full-deck searches. Keep specified top-card ordering. Draw or look at as many available cards as possible."}, {"type": "box", "title": "PAYMENT & FAILURE", "text": "A required recover/search target must exist before activation. A discard cost goes to the proper owner's graveyard. Defeat, cancellation, return or replacement never refunds coins. Empty decks skip draws; they do not cause a loss."}, {"type": "p", "text": "The searchable reference includes all 199 characters and 236 modifiers, including timing, costs, revised effects and the Transformation whitelist."}], "visual": "C156.png", "caption": null}, {"title": "Your first two turns", "kicker": "17 / A GUIDED OPENING", "blocks": [{"type": "p", "text": "This teaching example uses hypothetical purchases and no special effects. Both players start with 100 coins and pay for two opening characters."}, {"type": "box", "title": "SETUP", "text": "You spend 6 + 8 = 14 coins, leaving 86. Your opponent spends 5 + 10 = 15, leaving 85. Both fields begin with two ready characters."}, {"type": "box", "title": "YOUR FIRST TURN - YOU GO FIRST", "text": "Draw one of each card type. Buy a third character for 4: 82 coins remain. That new character waits. You may use one legal special and one modifier if desired, paying their costs. You cannot declare an attack this turn."}, {"type": "box", "title": "OPPONENT'S FIRST TURN", "text": "They draw and prepare. Under digital v2 they cannot attack with an eligible opening character. On their second turn, if a 10-Attack hit reaches one of your fresh 20-Defense characters with no Guard, it has 10 health left. Your defender does not automatically retaliate."}, {"type": "box", "title": "YOUR SECOND TURN", "text": "Refresh, draw and prepare. Last turn's purchase is now ready. Choose your one normal attack. Damage on the injured character remains. Buying, a special and a modifier still have separate limits."}, {"type": "p", "text": "When comparing the page-22 older rule, the opponent skips their opening attacks too. Everything else in this example stays the same."}], "visual": null, "caption": null}, {"title": "A modifier in action", "kicker": "18 / ANIMAL WHISPER", "blocks": [{"type": "p", "text": "Animal Whisper (M001) costs 7 and has Action timing. The example below uses its revised v2 text."}, {"type": "box", "title": "NORMAL USE", "text": "In Prepare, choose an opposing Animal that is not Legendary. You need an open slot. Pay 7 and announce the modifier. If it resolves, control that character until cleanup. It keeps its damage, cannot attack and cannot use its special."}, {"type": "box", "title": "SPECIAL BONUS ALTERNATIVE", "text": "If you control The Fogmaster, you may instead return one Animal from either character graveyard to its owner's hand. This explicit alternative needs no control target or open slot. It does not put that Animal directly into play."}, {"type": "box", "title": "IF THE OPPONENT CANCELS IT", "text": "Their legal cancellation response resolves first. The modifier's base and bonus fail, your 7 coins remain spent, and your own-turn modifier allowance is used."}, {"type": "p", "text": "This shows why the condition and exact wording matter: most bonuses improve a base effect, while this one explicitly substitutes an alternative. It also works as a base modifier without its named partner."}], "visual": "M001.png", "caption": null}, {"title": "Endings & questions", "kicker": "19 / CLEAR RULINGS", "blocks": [{"type": "box", "title": "WHEN DO I LOSE?", "text": "Your field is empty at your own cleanup. An opponent clearing it does not immediately end the game; you get your next turn to rebuild."}, {"type": "box", "title": "CAN I RUN OUT OF CARDS?", "text": "Yes. Skip draws from empty decks. No deck-out loss. At cleanup keep at most 5 characters and 5 modifiers in hand."}, {"type": "box", "title": "CAN I SPEND THE + NUMBER?", "text": "You pay that many coins to activate the special. It is not income, a recurring payout or an Attack bonus."}, {"type": "box", "title": "DO I HAVE TO ATTACK?", "text": "No. Actions are optional, but an empty field still loses at cleanup."}, {"type": "box", "title": "WHEN IS IT A STALL DRAW?", "text": "After 2 complete rounds with no damage, no character entering/leaving play, and no hand/deck/graveyard change except mandatory draws and hand-limit discards. A round is one turn for each player. Do not choose a winner by coins."}, {"type": "p", "text": "The 120-turn cap belongs to the simulator only. It is not a normal victory rule. If a situation is not covered, pause and record the card IDs, targets and timing for a playtest ruling."}], "visual": null, "caption": null}, {"title": "The next opening test", "kicker": "20 / OPTIONAL PLAYTEST VARIANT", "blocks": [{"type": "box", "title": "BOTH PLAYERS SKIP THEIR FIRST ATTACK", "text": "Digital default: neither player may declare a normal or extra attack on their own first turn. Buying, specials, modifiers and direct damage still work. Ready cannot bypass it."}, {"type": "results"}, {"type": "p", "text": "The 800-match comparison used 200 matched deck pairs, each played in both seats under both rules. No match stalled or reached the simulator cap. Median length rose from 25 to 26 individual player turns."}, {"type": "box", "title": "PROMISING, STILL PROVISIONAL", "text": "The new option was closer to 50/50 in this sample, but the uncertainty interval does not establish a clear improvement. All 240 historical control winners matched; six games differed in duration or coins. Exact cross-run replay remains unresolved."}, {"type": "p", "text": "These are heuristic-bot results, not human enjoyment tests or proof of all card combinations. This book follows the digital game: both players skip opening attacks. The older reference engine only skips the first player; use the game playtest switch to compare."}, {"type": "box", "title": "HUMAN PLAYTEST NOTES", "text": "Record opening rule, winner, who went first, turns, cards that felt unclear, and any long inactive stretch. Keep costs and stats unchanged while comparing the opening rules."}], "visual": null, "caption": null}, {"title": "Timing at a glance", "kicker": "21 / THE SHARED VOCABULARY", "blocks": [{"type": "list", "items": ["Action - Prepare only.", "Attack - after targets are announced, during attacking effects, before defense responds.", "Response - the defender's one legal response window.", "Either - a legal Prepare, attacking-effect or defensive window as the card permits.", "After attack - after the normal attack resolves or is canceled.", "Ready - an explicit exception to the entry delay; it grants no extra action and ignores no opening restriction.", "Next battle - next battle or the start of the effect controller's next turn, whichever comes first.", "For this battle - only the announced battle; expires if it is canceled.", "Cleanup - effect endings, temporary returns, hand limits and the active player's empty-field loss check.", "Once per game - tracked across zone changes and temporary control.", "Owner - the player whose deck the card came from.", "Controller - the player currently controlling it in play."]}, {"type": "p", "text": "Until start of turn, until end of turn and until end of next turn are different instructions. Expire each at the exact named boundary. The card register is the source for specific durations."}], "visual": null, "caption": null}, {"title": "Keep this page handy", "kicker": "22 / QUICK REFERENCE", "blocks": [{"type": "quick"}, {"type": "box", "title": "ONE TURN", "text": "Refresh & draw -> Prepare -> Battle -> Cleanup. Entry normally waits. Digital v2 both players skip normal and extra attacks on their first turn."}, {"type": "box", "title": "ONE BATTLE", "text": "Declare targets -> attacking effects -> one defensive response -> resolve damage -> defeat / after-battle effects. No ordinary counterattack. No response chains."}, {"type": "box", "title": "ONE DAMAGE RULE", "text": "Damage stays. Printed Defense is health. Guard blocks; Exposure weakens Guard. Final Attack zero deals zero. Direct damage bypasses Guard."}, {"type": "p", "text": "Find exact revised card wording in Card Reference. Use the full rules source for detailed rulings. Playtest edition dated 22 November 2026."}], "visual": "brand-icon.png", "caption": null}];
